import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"정약용에 대한 학계의 평가","slug":"정약용에-대한-학계의-평가","link":"#정약용에-대한-학계의-평가","children":[]},{"level":2,"title":"정약용의 삶과 문제의식","slug":"정약용의-삶과-문제의식","link":"#정약용의-삶과-문제의식","children":[]},{"level":2,"title":"우주론: 리기론의 해체","slug":"우주론-리기론의-해체","link":"#우주론-리기론의-해체","children":[]},{"level":2,"title":"심성론: 성기호설(性嗜好說)","slug":"심성론-성기호설-性嗜好說","link":"#심성론-성기호설-性嗜好說","children":[]},{"level":2,"title":"성기호설의 의의","slug":"성기호설의-의의","link":"#성기호설의-의의","children":[]}],"relativePath":"philosophy/Korean-Philosophy/12. 정약용의 성기호설.md","filePath":"philosophy/Korean-Philosophy/12. 정약용의 성기호설.md"}'),e={name:"philosophy/Korean-Philosophy/12. 정약용의 성기호설.md"};function g(a,t,u,l,q,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="정약용에-대한-학계의-평가" tabindex="-1">정약용에 대한 학계의 평가 <a class="header-anchor" href="#정약용에-대한-학계의-평가" aria-label="Permalink to &quot;정약용에 대한 학계의 평가&quot;">​</a></h2><p>다산 정약용(1762~1836)은 흔히 세 가지로 평가된다. ①&quot;조선 후기 실학을 집대성한 사상가&quot; — 이론적 실학과 경세 실학을 통합하고 중국 중심이 아닌 조선 현실에 맞는 개혁 방안을 제시함(『경세유표』: 관료제·행정조직 개선안, 『목민심서』: 지방수령의 공공윤리·행정안, 『흠흠신서』: 억울한 옥사·고문 남용·부패한 재판 관행 비판). ②&quot;실천적 유가철학의 정점&quot; — 주자학의 형이상학적 경향을 비판하면서도(반/탈주자학) 유가의 도덕 원리 자체는 계승하려 함 — 리기론을 해체하고 <strong>성기호설</strong>·심성일원론을 통해 도덕성·감정·욕망의 조화를 모색하고, 맹자의 민본주의를 계승함. ③&quot;제도 개혁을 통한 유교의 현실화를 모색한 사상가&quot; — 이상적 도덕만을 강조하는 유교를 넘어 제도와 법의 중요성을 인식한 개혁가로, 도덕성은 제도와 상호작용해야 실현될 수 있다는 현실주의적 인식을 가짐.</p><p>&#39;실학&#39;이라는 개념 자체는 이우성이 1960~70년대에 체계화한 것으로, 이후 문학·역사학계에서 &quot;근대지향적이고 민족자주성을 담은 사상운동&quot;으로 폭넓게 수용됨. 다만 이 틀을 액면 그대로 받아들이는 데는 유의가 필요하다 — 예컨대 실학자들의 경제관은 애덤 스미스식 자유방임(개인이 자신의 이익을 자유롭게 추구함으로써 &#39;보이지 않는 손&#39;에 이끌려 공익이 증진된다는 논리, 사유재산 강조)과는 결이 다르며, 오히려 맹자의 &quot;하필왈리(何必曰利, 어찌 굳이 이익을 말하는가)&quot;라는 가르침을 수용해 경쟁보다 조화, 소유보다 가치, 고립적 자아보다 관계적 자아를 중시하고 상공업보다 사(士)와 농(農)을 중시하는 흐름이 강함. 실학을 곧바로 &quot;근대적 학풍&quot;과 동일시하는 것은 지나친 단순화일 수 있음.</p><h2 id="정약용의-삶과-문제의식" tabindex="-1">정약용의 삶과 문제의식 <a class="header-anchor" href="#정약용의-삶과-문제의식" aria-label="Permalink to &quot;정약용의 삶과 문제의식&quot;">​</a></h2><p>정약용은 15세에 성균관에 유학하며 이가환·이승훈(이익의 학문을 이음)과 교유했고, 22세에 정조가 내린 『중용』 강의에서 이벽과 함께 답안을 작성함 — 이때 리발기발에 대해 이벽은 퇴계의 학설을, 정약용 자신은 우연히 율곡과 같은 입장을 취함. 1791년 최초의 천주교 박해사건인 진산사건, 1795년 주문모 사건 등을 거치며 여러 차례 좌천되었고, 1801년(순조 1년, 40세)부터 1818년까지 18년간 강진에서 유배 생활을 하며 방대한 저술을 남김.</p><p>18세기 후반~19세기 초 조선 사회는 성리학이 교조화되어 현실과 유리되어 있었다는 것이 정약용의 진단이다 — ①주자의 경전 해석이 절대화되어 학문이 의례적·형식적·추상적으로 흐르고, ②사서삼경 중심의 암기 교육으로 도덕이 삶의 문제가 아닌 시험·이론의 대상이 되고, ③현실과 단절된 채 기아·빈곤·부정부패가 만연했지만 실질적 대책보다 공리공담이 우선시되고, ④주자학 외의 해석을 이단(사문난적)으로 몰아 사상 탄압과 정체가 초래됨. 정약용의 문제의식은 결국 **&quot;어떻게 모든 인간에게 내재된 선한 도덕적 성향을 실현 가능한 윤리로 끌어올릴 것인가&quot;**라는 실천적 고민이었다 — &quot;도덕은 추상적 관념이 아니라 현실을 변화시키는 실천적 힘이어야 한다.&quot;</p><h2 id="우주론-리기론의-해체" tabindex="-1">우주론: 리기론의 해체 <a class="header-anchor" href="#우주론-리기론의-해체" aria-label="Permalink to &quot;우주론: 리기론의 해체&quot;">​</a></h2><p>정약용은 생애 두 차례(23세, 53세) 성리학의 리(理) 개념을 비판한다. 23세 때는 『중용강의보』에서 마테오 리치의 『천주실의』에 근거해 비판했고, 53세 때는 『맹자요의』에서 훈고학적 방식으로 비판함(비판이 이렇게 많지 않았던 것은, 교조화된 시대에 주자학 핵심 개념 비판에 심리적 부담을 느꼈고, 또 그의 주된 관심이 우주론보다 인성론에 있었기 때문으로 보임. 23세와 53세의 비판 방식이 다른 것도 각각 『천주실의』가 설득력 있어 보였던 시기와, 강진 유배 중 천주교 혐의를 조금도 받고 싶지 않았던 시기라는 정황 차이 때문으로 추정됨).</p><p><strong>23세, 『중용강의보』</strong>: 정조가 물었다 — 동유(율곡을 가리킴)의 논리대로 &quot;리와 기는 서로 혼합되어 원래 분리될 수 없고, 발현하는 것은 기이고 발현하게 하는 근원은 리&quot;라면, 어째서 사단은 리발에, 칠정은 기발에 배속시키는 이론(퇴계)이 나오는가? 정약용은 이렇게 답한다 — &quot;기는 <strong>&#39;스스로 존재하는 것&#39;</strong>(自有之物)이고, 리는 <strong>&#39;무엇인가에 붙어 있는 속성&#39;</strong>(依附之品)입니다. 붙어 있다는 것은 반드시 스스로 존재하는 것에 의존하므로, 잠시라도 기가 발할 때에만 리가 있게 됩니다. 그렇다면 &#39;기발이리승지&#39;는 가능하지만 &#39;리발이기수지&#39;는 불가능합니다.&quot; 리는 자립할 수 없으므로 먼저 발할 길이 없고, 발하려 할 때는 반드시 기가 앞선다는 것 — 즉 초기 정약용은 사단칠정을 막론하고 모든 현상은 <strong>&#39;기발이리승지&#39;</strong> 하나뿐이라며 이이 쪽의 논리를 지지함. &quot;풀 한 포기 나무 한 그루의 무성함과 새와 짐승이 날고 달리는 것도 &#39;氣發而理乘之&#39;가 아닌 것이 없다&quot;고까지 말함.</p><p>이후 정약용은 스스로 논의를 두 차례 수정한다. <strong>1차 수정</strong> — 이황과 이이의 논의는 애초에 맥락이 다르다는 것: 이황은 <strong>가치론적 입장</strong>(專就吾人性情上立說, 리=도심=천리성령, 기=인심=인욕혈기 — 이 맥락에서 사단은 리발, 칠정은 기발)에서 말한 것이고, 이이는 <strong>생성론적 입장</strong>(總括天地萬物而立說, 리=형이상자, 기=형이하자 — 이 맥락에서 모든 존재의 생성은 기발리승)에서 말한 것이므로 서로 다른 층위의 이야기라는 것. <strong>2차 수정</strong> — 논의의 주제(가치론·수양론)상 오히려 이황의 이론이 더 적절하다고 재평가함: 사단도 칠정도 모두 내 마음에서 나오는 것이지, 마음에 리와 기라는 두 구멍이 따로 있어 각각 사단과 칠정을 내보내는 것이 아니다. 다만 군자가 고요할 때 존양하고 움직일 때 성찰하며 &quot;이 생각이 천리의 공정함에서 발한 것인가, 인욕의 사사로움에서 발한 것인가&quot;를 세밀히 살피는 <strong>실천적·수양론적 목적</strong>에서 퇴계가 리발·기발을 나누어 말한 것이라면, 그 의도를 깊이 체득하는 자야말로 퇴계의 충실한 제자가 될 것이라고 평가함.</p><p>정약용이 참조한 마테오 리치의 『천주실의』는 실재물을 <strong>자립자</strong>(自立者, 실체)와 <strong>의뢰자</strong>(依賴者, 속성)로 구분하고, &quot;리 역시 속성의 부류이므로 자립할 수 없는데 어떻게 다른 사물을 존재하게 할 수 있겠는가&quot;라고 논한다 — 정약용의 초기 리 비판은 이 구도를 그대로 계승한 것.</p><p><strong>53세, 『맹자요의』</strong>: 이번에는 훈고학적 방법을 동원한다. 정약용에 따르면 &#39;리(理)&#39;는 본래 옥이나 돌의 결(맥락)을 가리키는 말(<strong>脈理</strong>)이었고, 이것이 &#39;결을 따라 쪼아나간다&#39;(<strong>治理</strong>)를 거쳐 송사를 따지고 판결 내리는 일(<strong>法理</strong>)을 뜻하게 된 것 — 즉 &quot;성은 곧 리&quot;라는 성리학적 구도는 애초에 기원이 없는 비전통적 발상이라는 것. &quot;리란 애증도 희노도 없는 텅 비고 막막한, 이름도 실체도 없는 것인데 우리 인간이 이것을 부여받아 성을 받았다고 하는가!&quot;(『맹자요의』) 태극 개념에 대해서도 마찬가지로 — 태극은 &quot;아직 천지가 나누어지기 이전에 한데 엉겨 있으면서 유형한 것이 시작이 되는&quot; 것, 즉 <strong>하나의 원기(기)가 엉겨 이루어진 것</strong>에 불과하다고 봄.</p><h2 id="심성론-성기호설-性嗜好說" tabindex="-1">심성론: 성기호설(性嗜好說) <a class="header-anchor" href="#심성론-성기호설-性嗜好說" aria-label="Permalink to &quot;심성론: 성기호설(性嗜好說)&quot;">​</a></h2><p>정약용은 성리학이 말하는 <strong>본연지성</strong>을 정면으로 부정한다. &quot;성리학자들은 늘 성을 리라고 여긴다… 이것이 이른바 본연지성이다. 본연지성은 대소존비의 차등이 없고 다만 품수받은 형질에 따라 청탁과 편정이 있을 뿐이다… 이것은 명백히 인성과 수성(獸性)을 동일한 것으로 만들어버리는 것&quot;(『맹자요의』) — 인간의 본성과 동물의 본성을 하나의 동일한 리로 뭉뚱그리는 것은, 맹자가 개·소·사람의 성을 애써 구별하며 고자와 논쟁했던 것과 어긋난다는 비판이다. 나아가 &#39;본연(本然)&#39;이라는 말 자체가 유가 경전이 아니라 불교(『수능엄경』)에서 온 개념이라고 지적하며, &quot;아직 발하지 않았을 때에는 참으로 선이라고 말할 수 없다&quot;고 못박는다.</p><p>정약용은 성리학의 인성론과 정면으로 다른 대안을 제시한다.</p><blockquote><p>&quot;성이란 글자는 본래 **기호(嗜好)**의 욕구를 가리키는 것이었다. 기호라는 것은 본래 마음에서 생기는 것인데, 마음에서 생기는 것이라면 그것은 성이 아니겠는가! … 만일 기호가 아니라고 한다면 어찌 &#39;절제한다&#39;고 하였으며, &#39;참는다&#39;고 하였겠는가?&quot;(『염씨고문소증초』)</p></blockquote><p>즉 성리학자들의 말처럼 성이 명경지수(맑고 고요한 물)와 같은 마음의 본래 상태를 가리킨다면, &quot;성을 절제한다&quot;, &quot;성을 참는다&quot;는 표현 자체가 성립할 수 없다는 것 — 경전의 표현이 옳다면 성은 마음의 본질이 아니라 **마음의 특정한 성향(기호)**을 가리키는 개념일 수밖에 없다.</p><p><strong>주희와 정약용의 결정적 차이</strong>: 주희에게는 우주의 보편적 리가 인간에게 내재된 것이 곧 인의예지의 본성이고, 그 본성이 발현된 것이 측은·수오·사양·시비의 <strong>사단</strong>이다 — 즉 본성(사덕)이 먼저 있고 사단은 그 발현물이다. 반면 정약용에게는 복숭아씨와 같은 실체적 본성이란 애초에 존재하지 않고, 다만 <strong>선을 좋아하는 성향</strong>만 존재할 뿐이다 — 이 성향으로 인해 사단의 감정이 발현되며, 이 감정이 실제 행동(실천)으로 이어질 때 비로소 인의예지라는 덕목이 <strong>사후적으로</strong> 성립한다. 사덕이 사단을 낳는 것이 아니라, 거꾸로 사단의 실천이 쌓여 사덕이라는 이름을 얻는 것이다.</p><p>정약용은 인간에게 <strong>두 종류의 성향</strong>이 공존한다고 본다 — &quot;기질지성은 단것을 좋아하고 쓴 것을 싫어하며 향기를 좋아하고 악취를 싫어하는 것이며, 천명지성은 선을 좋아하고 악을 미워하며 의를 좋아하고 탐욕을 미워하는 것이다.&quot; <strong>기질지성</strong>(육체적 성향 — 배고프면 식욕, 이성을 보면 성욕, 피곤하면 휴식욕)과 <strong>천명지성</strong>(도덕적 성향 — 불의를 보면 분노, 타인의 고통을 보면 측은함)은 모두 마음속에서 실제로 경험되고 지각되는 <strong>심리적 실재</strong>라는 점에서는 같지만, 도덕적 성향은 교육과 습관을 통해 길러내야 할 실재인 반면 육체적 성향은 제어·조화시켜야 할 실재라는 점에서 다르다.</p><p><strong>마음의 세 이치</strong>(『심경밀험』): 정약용은 마음에 세 층위의 이치가 있다고 정리한다. ①<strong>본성</strong>(性) — 선을 즐거워하고 악을 부끄러워함(맹자의 성선설의 근거이나, 고정된 성향이 아니라 <strong>가능성</strong>일 뿐). ②<strong>권형</strong>(權衡) — 선을 행할 수도 악을 행할 수도 있는, 육체적 욕망과 윤리적 욕망이 내면에서 갈등할 때 선택·결단을 감행하는 주체적 계기(고자의 &#39;단수&#39; 비유, 양웅의 선악혼재설이 여기서 나옴). ③<strong>행사</strong>(行事) — 외물과의 접촉에 의해 촉발되는 실제 행위의 국면으로, 이 측면에서 보면 육체적 욕망을 극복하고 선을 행하기는 매우 어렵다(순자의 성악설이 여기서 나옴). 즉 맹자·고자·순자의 성론은 서로 모순되는 것이 아니라, 마음의 서로 다른 세 층위를 각각 짚어낸 것이라는 게 정약용의 종합이다.</p><h2 id="성기호설의-의의" tabindex="-1">성기호설의 의의 <a class="header-anchor" href="#성기호설의-의의" aria-label="Permalink to &quot;성기호설의 의의&quot;">​</a></h2><p>주자학의 인성론은 &quot;모든 인간은 태어날 때부터 인의예지의 본성을 갖고 태어나며, 다만 부여받은 기질의 차이에 따라 선악의 차이가 발생한다&quot;는 구도로, 이는 일종의 <strong>도덕적 결정주의</strong>를 함축한다 — 인간 존재가 태어나는 순간 이미 도덕적으로 &#39;닫힌 존재&#39;로 규정되는 셈이다. 정약용도 혈기의 청탁에 따라 기질의 차이가 발생한다는 점 자체는 인정하지만, 그 차이를 지적 능력(우둔함·총명함)이나 정서적 민감성 등 <strong>도덕성과 무관한 특성</strong>으로 재규정하며, 그것이 도덕적 선악 판단의 기준이 될 수 없다고 본다.</p><p>정약용에 따르면 인간의 도덕성을 좌우하는 결정적 요인은 외부로부터 주어진 기질이나 실체적 본성이 아니라, <strong>행위 주체의 자율적 실천과 도덕적 판단</strong>에 달려 있다 — 인간에게 주어진 것은 인의예지라는 실체가 아니라 단지 &quot;선을 좋아하고 악을 미워하는 도덕적 성향&quot;뿐이며, 이 성향은 방향성 차원에서 선하다고 평가할 수 있지만 그것이 도덕적 성취를 보장하지는 않는다. 요컨대 정약용은 맹자의 성선설을 일정 부분 수용하면서도, 도덕적 존재로서의 인간은 자신의 선택과 실천을 통해 스스로 완성되어간다는 점을 강조한다 — 선한 사람이 될 것인가 악한 사람이 될 것인가는 오직 개인의 자율적 판단과 실천에 달려 있다는 점에서, <strong>성기호설은 주체적이고 개방적인 도덕관</strong>을 지향한다고 평가할 수 있다.</p>',23)])])}const _=o(e,[["render",g]]);export{h as __pageData,_ as default};
